{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyMm+mgVaiNet8FOzD2dXGv2"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"BFWd1CkMGagp"},"outputs":[],"source":["\"\"\"\n","train_convnext_v2_sintese.py\n","\n","Este script reproduz a configuração que gerou os resultados reportados no artigo:\n","    Acurácia: 77.69% | MCC: 0.662 | AUC-ROC macro: 0.918\n","\n","NOTA SOBRE VARIABILIDADE ENTRE EXECUÇÕES:\n","Mesmo com hiperparâmetros centrais bem confirmados, versões anteriores deste\n","script (sem estas últimas correções) produziram acurácia final no teste\n","variando entre ~65% e ~75% em diferentes execuções (contra 77,69% do\n","artigo), com maior variação concentrada na classe OCA (apenas 12 amostras no\n","teste). As mudanças acima podem reduzir essa variância, mas não a eliminam\n","completamente — variação residual entre execuções ainda é esperada, mesmo\n","com seed fixo, devido a não-determinismo de operações de GPU/cuDNN.\n","\"\"\"\n","\n","import os\n","import random\n","import json\n","import numpy as np\n","import tensorflow as tf\n","import keras\n","\n","try:\n","    from google.colab import drive\n","    drive.mount('/content/drive', force_remount=False)\n","except Exception:\n","    print(\"⚠️ Não está no Colab ou Drive já montado — seguindo normalmente.\")\n","\n","from keras.layers import Dense, Dropout, GlobalAveragePooling2D, BatchNormalization\n","from keras.applications import ConvNeXtBase\n","from keras.applications.convnext import preprocess_input\n","from keras.optimizers import AdamW\n","from keras.callbacks import ReduceLROnPlateau, ModelCheckpoint\n","from sklearn.utils.class_weight import compute_class_weight\n","from sklearn.metrics import (\n","    classification_report, matthews_corrcoef, confusion_matrix,\n","    roc_auc_score, roc_curve, auc, precision_recall_curve,\n","    average_precision_score\n",")\n","from sklearn.preprocessing import label_binarize\n","import matplotlib.pyplot as plt\n","import itertools\n","\n","\n","SEED = 42\n","os.environ['PYTHONHASHSEED'] = str(SEED)\n","random.seed(SEED)\n","np.random.seed(SEED)\n","tf.random.set_seed(SEED)\n","\n","os.environ['TF_DETERMINISTIC_OPS'] = '1'\n","os.environ['TF_CUDNN_DETERMINISTIC'] = '1'\n","try:\n","    tf.config.experimental.enable_op_determinism()\n","except Exception as e:\n","    print(f\"⚠️ Não foi possível ativar determinismo total: {e}\")\n","\n","\n","IMG_SIZE            = 224\n","BATCH_SIZE           = 64\n","EPOCHS               = 50\n","NUM_CLASSES          = 4\n","CLASSES              = ['Benign', 'Healthy', 'OCA', 'OPMD']\n","EXPERIMENTO          = 'ConvNeXtBase_V2'\n","\n","CAMADAS_DESCONGELADAS = 40\n","\n","LEARNING_RATE        = 1e-2\n","WEIGHT_DECAY         = 1e-5\n","\n","\n","REDUCE_LR_FACTOR        = 0.2\n","REDUCE_LR_PATIENCE       = 4\n","MIN_LR                  = 0.0\n","\n","NPZ_DIR   = '/content/drive/MyDrive/Gabriel/Arquivos/ImagensE/npz_raw'\n","PASTA_OUT = '/content/drive/MyDrive/Gabriel/Arquivos/ImagensE/NovosTestes/ConvNeXtBase_V2_sintese'\n","os.makedirs(PASTA_OUT, exist_ok=True)\n","\n","\n","def converter(obj):\n","    \"\"\"Auxiliar para serializar tipos numpy em JSON.\"\"\"\n","    if isinstance(obj, (np.integer, np.int64, np.int32)):\n","        return int(obj)\n","    if isinstance(obj, (np.floating, np.float64)):\n","        return float(obj)\n","    if isinstance(obj, np.ndarray):\n","        return obj.tolist()\n","    raise TypeError(f'Não serializável: {type(obj)}')\n","\n","\n","# ═══════════════════════════════════════════════════════\n","# CARREGAMENTO DOS DADOS\n","# ═══════════════════════════════════════════════════════\n","def carregar_npz(split_name):\n","    \"\"\"\n","    Carrega um split (train/val/test) a partir de um arquivo .npz contendo\n","    os arrays 'X' (imagens, shape [N, 224, 224, 3]) e 'y' (rótulos inteiros 0-3).\n","\n","    Os splits devem ter sido gerados com estratificação por paciente\n","    (70% treino, 15% validação, 15% teste), garantindo que imagens do mesmo\n","    paciente não apareçam em conjuntos distintos (ver Seção 4.2 do artigo).\n","    \"\"\"\n","    path = os.path.join(NPZ_DIR, f'{split_name}.npz')\n","    data = np.load(path)\n","    X = data['X'].astype(np.float32)\n","    X = preprocess_input(X)\n","    y_raw = data['y'].astype(np.int64)\n","    y_onehot = keras.utils.to_categorical(y_raw, num_classes=NUM_CLASSES)\n","    print(f\"  {split_name}: {X.shape} | distribuição: \"\n","          f\"{dict(zip(*np.unique(y_raw, return_counts=True)))}\")\n","    return X, y_onehot, y_raw\n","\n","\n","print(\"Carregando dados NPZ...\")\n","X_train, y_train, y_train_raw = carregar_npz('train')\n","X_val,   y_val,   _           = carregar_npz('val')\n","X_test,  y_test,  y_test_raw  = carregar_npz('test')\n","\n","OCA_IDX = CLASSES.index('OCA')\n","COPIAS_EXTRAS_OCA = 3\n","\n","oca_mask = (y_train_raw == OCA_IDX)\n","X_oca = X_train[oca_mask]\n","y_oca_raw = y_train_raw[oca_mask]\n","\n","X_train = np.concatenate([X_train] + [X_oca] * COPIAS_EXTRAS_OCA, axis=0)\n","y_train_raw = np.concatenate([y_train_raw] + [y_oca_raw] * COPIAS_EXTRAS_OCA, axis=0)\n","\n","rng_shuffle = np.random.RandomState(SEED)\n","idx_shuffle = rng_shuffle.permutation(len(X_train))\n","X_train = X_train[idx_shuffle]\n","y_train_raw = y_train_raw[idx_shuffle]\n","\n","y_train = keras.utils.to_categorical(y_train_raw, num_classes=NUM_CLASSES)\n","\n","print(f\"Após oversample da classe OCA (+{COPIAS_EXTRAS_OCA} cópias extras): \"\n","      f\"{dict(zip(*np.unique(y_train_raw, return_counts=True)))}\")\n","\n","\n","class_weights_arr = compute_class_weight(\n","    'balanced', classes=np.unique(y_train_raw), y=y_train_raw\n",")\n","class_weights = dict(enumerate(class_weights_arr))\n","print(\"Class weights:\", {CLASSES[k]: round(v, 3) for k, v in class_weights.items()})\n","\n","\n","data_augmentation = keras.Sequential([\n","    keras.layers.RandomFlip(\"horizontal\"),\n","    keras.layers.RandomRotation(0.20),\n","    keras.layers.RandomZoom(0.20),\n","    keras.layers.RandomContrast(0.20),\n","    keras.layers.RandomTranslation(0.10, 0.10),\n","], name='augmentation')\n","\n","base_model = ConvNeXtBase(\n","    include_top=False,\n","    input_shape=(IMG_SIZE, IMG_SIZE, 3),\n","    weights='imagenet',\n",")\n","\n","\n","for layer in base_model.layers[:-CAMADAS_DESCONGELADAS]:\n","    layer.trainable = False\n","for layer in base_model.layers[-CAMADAS_DESCONGELADAS:]:\n","    layer.trainable = True\n","\n","model = keras.Sequential([\n","    data_augmentation,\n","    base_model,\n","    GlobalAveragePooling2D(),\n","    BatchNormalization(),\n","    Dropout(0.5),\n","    Dense(512, activation='relu'),\n","    BatchNormalization(),\n","    Dropout(0.4),\n","    Dense(NUM_CLASSES, activation='softmax'),\n","])\n","model.build((None, IMG_SIZE, IMG_SIZE, 3))\n","\n","total_params = model.count_params()\n","trainable_params = sum(tf.size(w).numpy() for w in model.trainable_weights)\n","print(f\"✅ ConvNeXt-Base carregado | Total: {total_params:,} | \"\n","      f\"Treináveis: {trainable_params:,}\")\n","\n","model.compile(\n","    optimizer=AdamW(learning_rate=LEARNING_RATE, weight_decay=WEIGHT_DECAY),\n","    loss='categorical_crossentropy',\n","    metrics=['accuracy'],\n",")\n","\n","callbacks = [\n","    ReduceLROnPlateau(\n","        monitor='val_loss',\n","        factor=REDUCE_LR_FACTOR,\n","        patience=REDUCE_LR_PATIENCE,\n","        min_lr=MIN_LR,\n","        verbose=1,\n","    ),\n","    ModelCheckpoint(\n","        filepath=os.path.join(PASTA_OUT, 'model_convnext_best.keras'),\n","        monitor='val_loss',\n","        save_best_only=True,\n","        verbose=0,\n","    ),\n","]\n","\n","print(\"\\n🚀 Iniciando treino...\")\n","history = model.fit(\n","    X_train, y_train,\n","    validation_data=(X_val, y_val),\n","    epochs=EPOCHS,\n","    batch_size=BATCH_SIZE,\n","    class_weight=class_weights,\n","    callbacks=callbacks,\n","    verbose=1,\n",")\n","\n","with open(os.path.join(PASTA_OUT, 'convnext.json'), 'w') as f:\n","    json.dump(history.history, f)\n","print(\"✅ Histórico salvo\")\n","\n","\n","melhor_modelo_path = os.path.join(PASTA_OUT, 'model_convnext_best.keras')\n","model.load_weights(melhor_modelo_path)\n","print(f\"✅ Pesos do melhor checkpoint recarregados de: {melhor_modelo_path}\")\n","\n","\n","test_loss, test_acc = model.evaluate(X_test, y_test, verbose=1)\n","pred_prob = model.predict(X_test, verbose=0)\n","y_pred = np.argmax(pred_prob, axis=1)\n","y_true = np.argmax(y_test, axis=1)\n","\n","mcc = matthews_corrcoef(y_true, y_pred)\n","y_true_bin = label_binarize(y_true, classes=list(range(NUM_CLASSES)))\n","auc_macro = roc_auc_score(y_true_bin, pred_prob, multi_class='ovr', average='macro')\n","\n","print(f\"\\n{'=' * 55}\")\n","print(f\"RESULTADOS — {EXPERIMENTO}\")\n","print(f\"{'=' * 55}\")\n","print(f\"Acurácia:      {test_acc:.4f}  (esperado ≈ 0.7769)\")\n","print(f\"MCC:           {mcc:.4f}  (esperado ≈ 0.6620)\")\n","print(f\"AUC-ROC macro: {auc_macro:.4f}  (esperado ≈ 0.9180)\")\n","print(f\"{'=' * 55}\")\n","print(classification_report(y_true, y_pred, target_names=CLASSES, zero_division=0))\n","print(\"Matriz de Confusão:\")\n","print(confusion_matrix(y_true, y_pred))\n","\n","\n","diagnostico = {\n","    'experimento': EXPERIMENTO,\n","    'hiperparametros': {\n","        'backbone': 'convnext_base',\n","        'camadas_descongeladas': CAMADAS_DESCONGELADAS,\n","        'img_size': IMG_SIZE,\n","        'batch_size': BATCH_SIZE,\n","        'epochs_max': EPOCHS,\n","        'seed': SEED,\n","        'optimizer': 'adamw',\n","        'lr_inicial': LEARNING_RATE,\n","        'weight_decay': WEIGHT_DECAY,\n","        'loss': 'categorical_crossentropy',\n","        'reduce_lr_factor': REDUCE_LR_FACTOR,\n","        'reduce_lr_patience': REDUCE_LR_PATIENCE,\n","        'dropout_1': 0.5,\n","        'dropout_2': 0.4,\n","        'dense_units': 512,\n","        'augmentation': [\n","            'random_flip_horizontal',\n","            'random_rotation_20',\n","            'random_zoom_20',\n","            'random_contrast_20',\n","            'random_translation_10',\n","        ],\n","        'class_weight': 'balanced',\n","        'dataset': 'Piyarathne et al. 2024 — 3000 imagens / 714 pacientes',\n","        'split': '70/15/15 por paciente',\n","    },\n","    'metricas': {\n","        'acc': float(test_acc),\n","        'mcc': float(mcc),\n","        'auc_macro': float(auc_macro),\n","    },\n","    'classification_report': classification_report(\n","        y_true, y_pred, target_names=CLASSES, output_dict=True, zero_division=0\n","    ),\n","    'matriz_confusao': confusion_matrix(y_true, y_pred).tolist(),\n","}\n","with open(os.path.join(PASTA_OUT, 'diagnostico_completo.json'), 'w') as f:\n","    json.dump(diagnostico, f, indent=2, default=converter)\n","print(\"✅ diagnostico_completo.json salvo\")\n","\n","epochs_range = range(1, len(history.history['loss']) + 1)\n","\n","# --- Curvas de treinamento ---\n","fig, axes = plt.subplots(1, 2, figsize=(12, 4))\n","axes[0].plot(epochs_range, history.history['accuracy'], label='Treino', color='steelblue')\n","axes[0].plot(epochs_range, history.history['val_accuracy'], label='Validação', color='tomato')\n","axes[0].set_title('Acurácia')\n","axes[0].set_xlabel('Época')\n","axes[0].legend()\n","axes[0].grid(alpha=0.3)\n","\n","axes[1].plot(epochs_range, history.history['loss'], label='Treino', color='steelblue')\n","axes[1].plot(epochs_range, history.history['val_loss'], label='Validação', color='tomato')\n","axes[1].set_title('Loss')\n","axes[1].set_xlabel('Época')\n","axes[1].legend()\n","axes[1].grid(alpha=0.3)\n","\n","plt.suptitle(f'Curvas de Treinamento — {EXPERIMENTO}', fontweight='bold')\n","plt.tight_layout()\n","plt.savefig(os.path.join(PASTA_OUT, 'training_curves.png'), dpi=150, bbox_inches='tight')\n","plt.close()\n","\n","# --- Matriz de confusão ---\n","cm = confusion_matrix(y_true, y_pred)\n","cm_norm = cm.astype('float') / cm.sum(axis=1)[:, np.newaxis]\n","\n","fig, axes = plt.subplots(1, 2, figsize=(14, 5))\n","for ax, data_cm, title, fmt in zip(\n","    axes, [cm, cm_norm],\n","    ['Matriz de Confusão (absoluta)', 'Matriz de Confusão (normalizada)'],\n","    ['d', '.2f'],\n","):\n","    im = ax.imshow(data_cm, interpolation='nearest', cmap=plt.cm.Blues)\n","    ax.set_title(title, fontweight='bold')\n","    plt.colorbar(im, ax=ax)\n","    ticks = np.arange(len(CLASSES))\n","    ax.set_xticks(ticks); ax.set_xticklabels(CLASSES, rotation=45, ha='right')\n","    ax.set_yticks(ticks); ax.set_yticklabels(CLASSES)\n","    thresh = data_cm.max() / 2.\n","    for i, j in itertools.product(range(data_cm.shape[0]), range(data_cm.shape[1])):\n","        ax.text(j, i, format(data_cm[i, j], fmt), ha='center', va='center',\n","                 color='white' if data_cm[i, j] > thresh else 'black')\n","    ax.set_ylabel('Classe Real'); ax.set_xlabel('Classe Predita')\n","\n","plt.tight_layout()\n","plt.savefig(os.path.join(PASTA_OUT, 'confusion_matrix.png'), dpi=150, bbox_inches='tight')\n","plt.close()\n","\n","# --- Curva ROC ---\n","fpr, tpr, roc_auc_dict = {}, {}, {}\n","for i in range(NUM_CLASSES):\n","    fpr[i], tpr[i], _ = roc_curve(y_true_bin[:, i], pred_prob[:, i])\n","    roc_auc_dict[i] = auc(fpr[i], tpr[i])\n","\n","plt.figure(figsize=(7, 6))\n","colors = ['red', 'blue', 'green', 'purple']\n","for i, color in zip(range(NUM_CLASSES), colors):\n","    plt.plot(fpr[i], tpr[i], color=color, lw=2,\n","              label=f'{CLASSES[i]} (AUC = {roc_auc_dict[i]:.3f})')\n","plt.plot([0, 1], [0, 1], 'k--', lw=1, alpha=0.5)\n","plt.xlabel('Taxa de Falsos Positivos')\n","plt.ylabel('Taxa de Verdadeiros Positivos')\n","plt.title(f'Curva ROC Multiclasse — Macro-avg AUC = {auc_macro:.3f}', fontweight='bold')\n","plt.legend(loc='lower right')\n","plt.grid(alpha=0.3)\n","plt.tight_layout()\n","plt.savefig(os.path.join(PASTA_OUT, 'roc_curve.png'), dpi=150, bbox_inches='tight')\n","plt.close()\n","\n","# --- Curva Precision-Recall ---\n","precision_dict, recall_dict, ap_dict = {}, {}, {}\n","for i in range(NUM_CLASSES):\n","    precision_dict[i], recall_dict[i], _ = precision_recall_curve(\n","        y_true_bin[:, i], pred_prob[:, i]\n","    )\n","    ap_dict[i] = average_precision_score(y_true_bin[:, i], pred_prob[:, i])\n","\n","plt.figure(figsize=(7, 6))\n","for i, color in zip(range(NUM_CLASSES), colors):\n","    plt.plot(recall_dict[i], precision_dict[i], color=color, lw=2,\n","              label=f'{CLASSES[i]} (AP = {ap_dict[i]:.3f})')\n","plt.xlabel('Recall')\n","plt.ylabel('Precision')\n","plt.title('Curva Precision-Recall Multiclasse', fontweight='bold')\n","plt.legend(loc='lower left')\n","plt.grid(alpha=0.3)\n","plt.tight_layout()\n","plt.savefig(os.path.join(PASTA_OUT, 'pr_curve.png'), dpi=150, bbox_inches='tight')\n","plt.close()\n","\n","print(f\"\\n✅ Tudo salvo em: {PASTA_OUT}\")\n","print(\"Arquivos gerados:\")\n","print(\"  - model_convnext_best.keras\")\n","print(\"  - convnext.json (histórico)\")\n","print(\"  - diagnostico_completo.json\")\n","print(\"  - training_curves.png\")\n","print(\"  - confusion_matrix.png\")\n","print(\"  - roc_curve.png\")\n","print(\"  - pr_curve.png\")"]}]}